import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E7%9F%A5%E8%AF%86%E5%BA%93/%E5%88%B6%E9%80%A0%E4%B8%9A%E4%B8%9A%E5%8A%A1%E7%9F%A5%E8%AF%86/","title":"制造业业务知识 | notes","lang":"zh-CN","frontmatter":{"title":"制造业业务知识","createTime":"2026/04/04 23:19:53","permalink":"/notes/知识库/制造业业务知识/","description":"ERP 销售管理:承接客户订单与市场需求预测，作为整个系统的需求源头； 计划管理:以MRP引擎为核心，基于BOM多级展开与生产工艺路线，通过提前期倒排自动平衡库存、在制、在购资源，精准计算零部件及外购料的净需求，生成可执行的采购与生产计划； 采购管理:依据MRP建议自动下达采购订单，跟踪供应商交货与质量检验； 生产管理:按工单组织领料、工序流转与完工入...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"制造业业务知识\\",\\"image\\":[\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20260404212614778.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20260404213757936.png\\"],\\"dateModified\\":\\"2026-07-28T07:03:53.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E7%9F%A5%E8%AF%86%E5%BA%93/%E5%88%B6%E9%80%A0%E4%B8%9A%E4%B8%9A%E5%8A%A1%E7%9F%A5%E8%AF%86/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"制造业业务知识"}],["meta",{"property":"og:description","content":"ERP 销售管理:承接客户订单与市场需求预测，作为整个系统的需求源头； 计划管理:以MRP引擎为核心，基于BOM多级展开与生产工艺路线，通过提前期倒排自动平衡库存、在制、在购资源，精准计算零部件及外购料的净需求，生成可执行的采购与生产计划； 采购管理:依据MRP建议自动下达采购订单，跟踪供应商交货与质量检验； 生产管理:按工单组织领料、工序流转与完工入..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20260404212614778.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-07-28T07:03:53.000Z"}],["meta",{"property":"article:modified_time","content":"2026-07-28T07:03:53.000Z"}]]},"readingTime":{"minutes":12.55,"words":3764},"git":{"createdTime":1775331561000,"updatedTime":1785222233000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":1,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":2,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"6bf6089e08b96de5dfb1c64d5068f33e961b39b5","time":1785222233000,"email":"xiaofei00152@gmail.com","author":"731016","message":"制造业知识更新"},{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/知识库/制造业业务知识.md","headers":[],"bulletin":true}`),a={name:`制造业业务知识.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="erp" tabindex="-1"><a class="header-anchor" href="#erp"><span>ERP</span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>ERP协同生产管理系统实现产销财一体化管控：</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>销售管理：订单与预测双模式需求入口</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>计划管理：MRP引擎基于BOM+工艺倒排计划，自动计算物料净需求</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>采购管理：按MRP建议生成采购订单，跟踪到货与结算</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>生产管理：工单下发、领料控制、进度跟踪与完工入库</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>库存管理：多仓库实时管控，支持安全库存预警</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>财务管理：存货核算、成本归集与应收应付联动</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>销售管理:承接客户订单与市场需求预测，作为整个系统的需求源头；</p><p>计划管理:以MRP引擎为核心，基于BOM多级展开与生产工艺路线，通过提前期倒排自动平衡库存、在制、在购资源，精准计算零部件及外购料的净需求，生成可执行的采购与生产计划；</p><p>采购管理:依据MRP建议自动下达采购订单，跟踪供应商交货与质量检验；</p><p>生产管理:按工单组织领料、工序流转与完工入库，实时反馈进度异常；库存管理实现多仓库、多批次精细化管控，动态预警安全库存与呆滞物料；</p><p>财务管理:自动归集采购、生产、销售环节的成本与应收应付数据，保障账实一致与利润精准核算。</p><h3 id="mrp核心逻辑" tabindex="-1"><a class="header-anchor" href="#mrp核心逻辑"><span>MRP核心逻辑</span></a></h3><p>MRP（Material Requirements Planning，物料需求计划）是一种生产管理和库存控制系统，用于制造业中确定生产所需的原材料、零部件和组件的需求量和需求时间。</p><p>&quot;从客户需求出发，按产品结构拆解，考虑现有资源，倒排时间节点，精准计算缺什么、缺多少、何时到位。&quot;</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20260404212614778.png" alt="image-20260404212614778" tabindex="0" loading="lazy"><figcaption>image-20260404212614778</figcaption></figure><p>一、时间主线 + 倒推逻辑</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>销售订单交货期 ──→ 成品装配 ──→ 零部件加工 ──→ 原材料采购</span></span>
<span class="line"><span>    ↑_________________________________________________|</span></span>
<span class="line"><span>                    （按提前期倒推）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>核心思想</strong>：从&quot;交货 deadline&quot;倒推，每个环节需要提前多久开始，才能保证最终按时交付。</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20260404213757936.png" alt="image-20260404213757936" tabindex="0" loading="lazy"><figcaption>image-20260404213757936</figcaption></figure><p>二、以 BOM 结构和生产工艺为依据 层级 示例（生产一台电脑） Level 0 成品电脑（销售订单对象） Level 1 机箱、主板、显示器、电源（自制件/外购件） Level 2 主板上的芯片、电容、插槽（原材料）</p><p><strong>BOM 展开</strong>：MRP 逐层拆解，计算每一层物料的需求量和需求时间。 生产工艺：考虑每道工序的加工时间、顺序、产能约束。</p><p>三、以销售订单（或预测）为源头 需求来源 适用场景 销售订单 按单生产（MTO），客户已下单 销售预测 备货生产（MTS），基于市场需求预测</p><p>毛需求 = 订单数量（或预测数量）</p><p>四、平衡库存、在制、在购 <code>净需求 = 毛需求 - 现有库存 - 在途订单 + 安全库存 + 已分配量</code></p><p>项目 含义 作用 库存 仓库里现有的 直接可用，减少新需求 在制 车间正在生产的 即将入库，减少新需求 在购 已下单未到货的 即将到货，减少新需求</p><p>避免重复采购/生产，这是 MRP 的核心价值之一。</p><p>五、通过提前期倒推，生成净需求计划</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>交货期：4月30日</span></span>
<span class="line"><span>├── 成品装配提前期：3天 → 4月27日开始装配</span></span>
<span class="line"><span>├── 零部件加工提前期：5天 → 4月22日开始加工</span></span>
<span class="line"><span>└── 原材料采购提前期：10天 → 4月12日下达采购单</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>计划产出：</p><p>生产计划：何时开工、生产多少、哪条产线</p><p>采购计划：何时下单、采购多少、供应商是谁</p><p>六、保证及时配套和按期交付 目标 MRP 如何实现 及时配套 所有物料按同一时间到达，避免&quot;料等人&quot;或&quot;人等料&quot; 按期交付 倒排计划确保每个环节不延误 降低库存 按需采购，减少资金占用</p><h2 id="mes" tabindex="-1"><a class="header-anchor" href="#mes"><span>MES</span></a></h2><p>生产制造执行系统</p><p>MES是连接ERP与底层自动化设备的桥梁，负责将生产计划转化为车间可执行的生产任务，并实时监控执行过程。</p><h3 id="流程制造mes-烟草行业示例" tabindex="-1"><a class="header-anchor" href="#流程制造mes-烟草行业示例"><span>流程制造MES（烟草行业示例）</span></a></h3><p>适用于食品饮料、化工、药品、烟草等连续生产行业，成品是连续物料，不可拆分。</p><h4 id="生产工单" tabindex="-1"><a class="header-anchor" href="#生产工单"><span>生产工单</span></a></h4><p>车间人员下发生产指令到底层数采系统（信息包括牌号等信息），数采系统解析后返回工单号，机台，批次等信息，mes生成生产工单；</p><p>产量分为数采产量和车间人员填写的实际的产量，可能有抽检或其他用途和数采系统有出入</p><p>工单状态通过数采系统反馈</p><p>由车间人员通过每个牌号的产量确认单填写，可能有各个工序的不同的数量</p><h4 id="出入库" tabindex="-1"><a class="header-anchor" href="#出入库"><span>出入库</span></a></h4><p>生产牌号需要的物料的库存管理，主要负责专注于物料从收货-&gt;检验-&gt;出库投入生产这个流程的控制 收货需要创建在MES创建入库单，由WMS物流管理平台发送数据到MES，进行收货；MES校验货物信息（货物数量）后，根据物料的检验标准创建报检单进行抽检，抽检合格后入库</p><h4 id="检验工单" tabindex="-1"><a class="header-anchor" href="#检验工单"><span>检验工单</span></a></h4><p>通过维护牌号工艺标准或生产牌号的原料的检验信息，如烟丝的烘丝温度，接装纸的抗张拉力强度</p><p>通过生产工单和检验标准创建检验工单进行检验，现场使用检查仪器，数采数据通过开发的net桌面程序，通过udp、tcp、opc、串口通信上传至检验工单</p><h4 id="数据采集" tabindex="-1"><a class="header-anchor" href="#数据采集"><span>数据采集</span></a></h4><p>监控数采数据，计算CPK,PPK..质量参数，生成监控图形</p><p>通过创建的工艺标准下发的数采底层系统，PLC通过OPC协议上传至Wonderware数据库，包含牌号，批次，工单号等信息</p><p>通过kafka采集Wonderware数据库的实时数据，并处理计算需要的数据，通过websocket推送至前台展示实时监控图形</p><h4 id="生产流程" tabindex="-1"><a class="header-anchor" href="#生产流程"><span>生产流程</span></a></h4><p>用户负责对成品烟进行排产，排出生产计划，计划导入mes系统，具体到机台，这个机台今天生产多少箱烟</p><p>一个新的牌号</p><p>牌号基础信息由中烟主数据下发</p><p>用户在mes系统维护牌号的工艺信息（制丝、卷包的质量参数、工序信息下发到底层集控系统），这些信息会在数采时使用</p><p>用户下发生产指令单（牌号等信息）给底层集控系统，交互使用中间表交互，集控解析信息后返回生产工单信息（包括班次，开始结束时间，牌号，批次，工单号等），生产工单的生产状态（下发PLC，开工，完成）由集控系统通过接口返回</p><p>产量由产量确认单提供，绑定到工单，部分信息（数采产量）由底层系统提供，部分由用户填写，完工时会走审批流程手动确认</p><p>生产用到的材料通过出入库记录来绑定工单号</p><p>物料入库，入库单由WMS接口提供，可能一个单据有多个材料，收货后对应明细都会生成一条单据</p><p>收货时，生成材料检验单，提交后会生成检验工单，这里没有堵死，只是记录一个流程，这里收货后单据状态就是完全收货了</p><p>这里的物料检验由实验室完成，通过tcp、ucp、opc、串口传输到mes系统的检验工单明细</p><p>生产消耗</p><p>每个机台用了多少材料信息由WMS提供，只有总的材料量；没有记录如果这个机台有多的材料借给别的机台用了，通过用户手动录入，mes再班次结束是自动汇总计算</p><h3 id="离散制造mes-机械-电子行业示例" tabindex="-1"><a class="header-anchor" href="#离散制造mes-机械-电子行业示例"><span>离散制造MES（机械/电子行业示例）</span></a></h3><p>适用于机械、家电、五金、电子设备等行业，产品由多个零部件组成，可拆解，工序离散、可跳转。</p><h4 id="核心业务模块" tabindex="-1"><a class="header-anchor" href="#核心业务模块"><span>核心业务模块</span></a></h4><p><strong>1. 主数据管理（MD）</strong></p><ul><li><strong>物料管理（MdItem）</strong>: 物料/产品编码、名称、规格型号、单位、安全库存、批次管理、库存上限下限、是否允许负库存</li><li><strong>BOM管理（MdBom）</strong>: 多级BOM结构（头记录+行记录）、版本控制、用量、损耗率、BOM变更记录</li><li><strong>客户管理（MdClient）</strong>: 客户编码、名称、简称</li><li><strong>供应商管理（MdVendor）</strong>: 供应商编码、名称、简称</li><li><strong>车间管理（MdWorkshop）</strong>: 车间编码、名称</li></ul><p><strong>2. 生产管理（Pro）</strong></p><ul><li><strong>生产工单（ProWorkorder）</strong>: 工单类型、订单来源、产品信息、数量、批次、客户/供应商、需求日期、工艺路线、已生产数量、状态</li><li><strong>工艺路线（ProRoute）</strong>: 路线编号、名称、画布JSON数据（可视化流程）、是否启用</li><li><strong>工序定义（ProProcess）</strong>: 工序编码、名称、注意事项、是否启用</li><li><strong>生产任务（ProTask）</strong>: 关联工单、工作站、工序、排产数量、已生产数量、合格/不合格数量、报工管理、开始/结束时间、实际开工时间、甘特图颜色</li><li><strong>工序流转卡（ProCard）</strong>: 绑定工单、批次、流转数量、状态、赋码地址、当前工作站</li></ul><p><strong>3. 质量管理（QC）</strong></p><ul><li><strong>来料检验（QcIqc）</strong>: 供应商信息、物料信息、接收数量、检测数量、合格/不合格数、缺陷率（致命/严重/轻微）、检验模板、来源单据</li><li><strong>过程检验（QcIpqc）</strong>: 关联工单/任务/工作站/工序、检测数量、合格/不合格数、缺陷分类、检验结果</li><li><strong>出货检验（QcOqc）</strong>: 客户信息、批次、发货数量、检测数量、合格/不合格数、出货日期</li><li><strong>退货检验（QcRqc）</strong>: 退货检验单管理</li><li><strong>缺陷管理（QcDefect）</strong>: 缺陷类型定义、缺陷记录</li><li><strong>检验指标（QcIndex）</strong>: 检验指标定义</li></ul><p><strong>4. 仓储管理（WM）</strong></p><ul><li><strong>条码管理（WmBarcode）</strong>: 条码生成、条码配置</li><li><strong>批次管理（WmBatch）</strong>: 批次追踪</li><li><strong>序列号管理（WmSn）</strong>: 产品序列号追溯</li><li><strong>生产领料（WmIssue）</strong>: 工单领料、发料明细</li><li><strong>生产退料（WmRtIssue）</strong>: 退料单、退料类型、关联工单/工作站</li><li><strong>产品入库（WmProductRecpt）</strong>: 成品入库</li><li><strong>销售出库（WmRtSales）</strong>: 销售发货</li><li><strong>调拨管理（WmTransfer）</strong>: 仓库间调拨</li><li><strong>库存盘点（WmStockTaking）</strong>: 盘点任务、盘点结果</li></ul><p><strong>5. 设备管理（DV）</strong></p><ul><li><strong>设备管理（DvMachinery）</strong>: 设备编码、名称、品牌、规格、类型、所属车间、最近保养/点检时间、设备状态</li><li><strong>设备维修（DvRepair）</strong>: 维修记录、维修明细</li><li><strong>点检管理（DvSubject）</strong>: 点检项目、点检计划、点检记录</li><li><strong>保养记录（DvMaintenRecord）</strong>: 设备保养历史</li></ul><p><strong>6. 工装夹具管理（TM）</strong></p><ul><li><strong>工装夹具（TmTool）</strong>: 编码、名称、品牌、型号、类型、数量、可用数量、保养周期、下次保养日期、状态</li><li><strong>夹具类型（TmToolType）</strong>: 夹具分类管理</li></ul><p><strong>7. 排班管理（Cal）</strong></p><ul><li><strong>排班计划（CalPlan）</strong>: 计划编号、名称、开始/结束日期、轮班方式、倒班方式、班次数量、状态</li><li><strong>班次定义（CalShift）</strong>: 班次时间定义</li><li><strong>班组管理（CalTeam）</strong>: 班组人员配置</li></ul><p><strong>8. 数据采集（IoT）</strong></p><ul><li><strong>PLC数据采集（PlcData）</strong>: 实时采集设备数据</li><li><strong>安灯系统（Andon）</strong>: 安灯配置、安灯记录</li><li><strong>OEE监控</strong>: 设备综合效率计算与监控</li></ul><h4 id="生产流程-1" tabindex="-1"><a class="header-anchor" href="#生产流程-1"><span>生产流程</span></a></h4><ol><li><strong>订单导入</strong>: 销售订单或预测计划导入MES，生成生产工单</li><li><strong>工单创建</strong>: 指定产品、数量、工艺路线、客户、需求日期</li><li><strong>任务派工</strong>: 根据工艺路线自动生成各工序生产任务，分配到具体工作站</li><li><strong>扫码报工</strong>: 工人通过PDA扫码开始执行任务，记录实际开工时间</li><li><strong>过程检验</strong>: 关键工序自动触发过程检验单（IPQC）</li><li><strong>工序流转</strong>: 通过流转卡（ProCard）跟踪物料在各工序间的流转</li><li><strong>完工入库</strong>: 最后一道工序完成后，产品入库</li><li><strong>出货检验</strong>: 发货前进行出货检验（OQC）</li><li><strong>销售出库</strong>: 检验合格后安排发货</li></ol><h4 id="核心特点" tabindex="-1"><a class="header-anchor" href="#核心特点"><span>核心特点</span></a></h4><ul><li><strong>BOM管理</strong>: 多级物料清单，支持版本控制和损耗率计算</li><li><strong>工艺路线</strong>: 可视化配置工序流程，支持并行和串行工序</li><li><strong>工单派工</strong>: 任务精确分配到工作站/设备/人员</li><li><strong>进度追踪</strong>: 实时跟踪每个工单、任务的完成进度</li><li><strong>序列号追溯</strong>: 支持单品级追溯（WmSn）</li><li><strong>质量三检</strong>: 来料检验（IQC）、过程检验（IPQC）、出货检验（OQC）</li><li><strong>设备管理</strong>: 设备台账、保养、维修、点检一体化管理</li><li><strong>工装夹具</strong>: 夹具生命周期管理、可用性跟踪</li></ul><h3 id="流程制造-vs-离散制造对比" tabindex="-1"><a class="header-anchor" href="#流程制造-vs-离散制造对比"><span>流程制造 vs 离散制造对比</span></a></h3><table><thead><tr><th>特性</th><th>流程制造</th><th>离散制造</th></tr></thead><tbody><tr><td><strong>行业示例</strong></td><td>食品饮料、化工、药品、烟草、油漆涂料</td><td>机械、家电、五金、电子设备</td></tr><tr><td><strong>产品形态</strong></td><td>连续物料，不可拆分</td><td>由多个零部件组成，可拆解</td></tr><tr><td><strong>生产方式</strong></td><td>流程连续、不可中断，多为流水线</td><td>工序离散、可跳转，多为工单制</td></tr><tr><td><strong>核心管理</strong></td><td>配方管理、批次追溯、质量实时监控</td><td>BOM管理、工艺路线、工单派工</td></tr><tr><td><strong>产量管理</strong></td><td>数采产量为主，人工确认补充</td><td>报工数量、合格/不合格数量统计</td></tr><tr><td><strong>物料追溯</strong></td><td>批次级追溯</td><td>序列号级追溯（单品级）</td></tr><tr><td><strong>设备管理</strong></td><td>PLC集成、实时数据采集</td><td>设备台账、保养维修点检</td></tr><tr><td><strong>典型MES功能</strong></td><td>牌号管理、工艺标准下发、实时监控图形</td><td>工序流转卡、生产任务管理、甘特图排程</td></tr></tbody></table><h3 id="流程制造核心要点" tabindex="-1"><a class="header-anchor" href="#流程制造核心要点"><span>流程制造核心要点</span></a></h3><p><strong>（1）配方管理</strong>：精确控制原材料比例、工艺参数，如烟草行业的制丝温度、接装纸规格</p><p><strong>（2）批次管理</strong>：完整追溯每个批次的生产时间、使用的原材料批次、生产设备、操作人员</p><p><strong>（3）质量控制</strong>：实时监控生产过程质量数据（如CPK、PPK参数），通过OPC协议采集PLC数据</p><h3 id="离散制造核心要点" tabindex="-1"><a class="header-anchor" href="#离散制造核心要点"><span>离散制造核心要点</span></a></h3><p><strong>（1）BOM管理</strong>：多级物料清单，支持版本控制和损耗率计算，精确知道产品需要哪些零件</p><p><strong>（2）工艺路线</strong>：可视化配置工序流程，定义每道工序、执行车间、预计工时，支持并行和串行</p><p><strong>（3）工单派工</strong>：将生产任务精确分配到工作站、设备或员工，支持扫码报工</p><p><strong>（4）进度追踪</strong>：实时跟踪每个工单、任务的完成进度，通过甘特图直观展示排程情况</p>`,94)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};